import { useChannelSounding } from '@pixelkit-labs/sdk';

function FindAccessory({ address }: { address: string }) {
  const { isSupported, isRanging, measurements, sessionError, startRanging, stopRanging } = useChannelSounding();
  if (!isSupported) return <Text>This device does not declare Channel Sounding</Text>;
  const latest = measurements.find((m) => m.deviceAddress === address.toUpperCase());
  return (
    <View>
      <Button
        title={isRanging ? 'Stop ranging' : 'Range accessory'}
        onPress={() => (isRanging ? stopRanging() : startRanging({ peerAddress: address }))}
      />
      {sessionError && <Text>{sessionError}</Text>}
      <Text>{latest?.distanceMeters != null ? `${latest.distanceMeters.toFixed(2)} m (${latest.confidence ?? 'confidence unknown'})` : '—'}</Text>
    </View>
  );
}
